using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.Extensions.AI.Evaluation.Reporting.Storage;
using OpenAI;

namespace MyApp.Evals;

internal static class EvalConfig
{
    private static readonly string ModelName =
        Environment.GetEnvironmentVariable("EVAL_MODEL") ?? "gpt-4o-mini";

    private static readonly string Endpoint =
        Environment.GetEnvironmentVariable("AZURE_OPENAI_ENDPOINT") ?? "https://localhost";

    private static readonly string ApiKey =
        Environment.GetEnvironmentVariable("AZURE_OPENAI_API_KEY") ?? "";

    public static IChatClient CreateChatClient()
    {
        var client = new Azure.AI.OpenAI.AzureOpenAIClient(
            new Uri(Endpoint),
            new System.ClientModel.ApiKeyCredential(ApiKey));

        return client.GetChatClient(ModelName).AsIChatClient();
    }

    public static IEvaluator[] QualityEvaluators(IChatClient judge) =>
    [
        new RelevanceEvaluator(judge),
        new CoherenceEvaluator(judge),
        new FluencyEvaluator(judge),
        new GroundednessEvaluator(judge),
    ];

    public static ReportingConfiguration CreateReportingConfig(
        string scenarioName,
        IEvaluator[] evaluators)
    {
        var storage = new DiskBasedResultStorage(
            Path.Combine("eval-results", scenarioName));

        return new ReportingConfiguration(evaluators, storage);
    }
}

using Microsoft.Extensions.AI;
using Microsoft.VisualStudio.TestTools.UnitTesting;
using OpenTelemetry;
using OpenTelemetry.Resources;
using OpenTelemetry.Trace;

namespace MyApp.Evals;

/// <summary>
/// Telemetry mode: validates that the agent emits expected spans and metrics
/// when OpenTelemetry is wired into the pipeline.
/// </summary>
[TestClass]
public class TelemetryTests
{
    private static readonly List<System.Diagnostics.Activity> ExportedActivities = [];

    private TracerProvider? _tracerProvider;

    [TestInitialize]
    public void Setup()
    {
        ExportedActivities.Clear();

        _tracerProvider = Sdk.CreateTracerProviderBuilder()
            .SetResourceBuilder(ResourceBuilder.CreateDefault().AddService("MyApp.Evals"))
            .AddSource("Microsoft.Extensions.AI")
            .AddSource("MyApp")
            .AddInMemoryExporter(ExportedActivities)
            .AddOtlpExporter(opt =>
            {
                var otlpEndpoint = Environment.GetEnvironmentVariable("OTEL_EXPORTER_OTLP_ENDPOINT");
                if (!string.IsNullOrEmpty(otlpEndpoint))
                    opt.Endpoint = new Uri(otlpEndpoint);
            })
            .Build();
    }

    [TestCleanup]
    public void Cleanup()
    {
        _tracerProvider?.Dispose();
    }

    [TestMethod]
    public async Task ChatCompletion_EmitsTraceSpan()
    {
        var innerClient = EvalConfig.CreateChatClient();
        using var client = new ChatClientBuilder(innerClient)
            .UseOpenTelemetry()
            .Build();

        await client.GetResponseAsync("What is 2+2?");

        _tracerProvider?.ForceFlush();

        Assert.IsTrue(
            ExportedActivities.Count > 0,
            "Expected at least one trace activity from the chat completion call.");
    }

    [TestMethod]
    public async Task ChatCompletion_SpanContainsModelAttribute()
    {
        var innerClient = EvalConfig.CreateChatClient();
        using var client = new ChatClientBuilder(innerClient)
            .UseOpenTelemetry()
            .Build();

        await client.GetResponseAsync("Say hello.");

        _tracerProvider?.ForceFlush();

        var span = ExportedActivities.FirstOrDefault();
        Assert.IsNotNull(span, "No span was exported.");

        var tags = span.Tags.ToDictionary(t => t.Key, t => t.Value);
        Assert.IsTrue(
            tags.ContainsKey("gen_ai.request.model") || tags.ContainsKey("gen_ai.response.model"),
            "Span should contain a model tag.");
    }
}

using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace MyApp.Evals;

/// <summary>
/// Quality mode: evaluates the agent's responses for relevance, coherence,
/// fluency, and groundedness using an LLM-as-judge approach.
/// </summary>
[TestClass]
public class QualityTests
{
    private IChatClient _chatClient = null!;
    private IChatClient _judgeClient = null!;
    private ReportingConfiguration _reporting = null!;

    [TestInitialize]
    public void Setup()
    {
        _chatClient = EvalConfig.CreateChatClient();
        _judgeClient = EvalConfig.CreateChatClient();

        var evaluators = EvalConfig.QualityEvaluators(_judgeClient);
        _reporting = EvalConfig.CreateReportingConfig("quality", evaluators);
    }

    [TestMethod]
    public async Task CoachResponse_MeetsQualityThresholds()
    {
        var scenario = await _reporting.CreateScenarioRunAsync(
            "coach-general-advice");

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "I'm feeling stuck on a project. What should I do?")
        };

        var response = await _chatClient.GetResponseAsync(messages);
        var modelResponse = response.Messages.Last();

        await scenario.EvaluateAsync(
            messages,
            modelResponse,
            additionalContext:
            [
                new EvaluationContext(
                    "grounding",
                    "A coach should provide actionable advice to help someone get unstuck on a project.")
            ]);

        foreach (var result in scenario.GetResults())
        {
            if (result.Value is NumericMetricValue numericValue)
            {
                Assert.IsTrue(
                    numericValue.Value >= 3,
                    $"Metric '{result.Key}' scored {numericValue.Value}/5, expected >= 3.");
            }
        }

        await scenario.DisposeAsync();
    }

    [TestMethod]
    public async Task CoachResponse_HandlesFollowUp()
    {
        var scenario = await _reporting.CreateScenarioRunAsync(
            "coach-follow-up");

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "How do I prioritize tasks?"),
            new(ChatRole.Assistant, "Try the Eisenhower matrix to sort by urgency and importance."),
            new(ChatRole.User, "Can you give me a concrete example?")
        };

        var response = await _chatClient.GetResponseAsync(messages);
        var modelResponse = response.Messages.Last();

        await scenario.EvaluateAsync(messages, modelResponse);

        foreach (var result in scenario.GetResults())
        {
            if (result.Value is NumericMetricValue numericValue)
            {
                Assert.IsTrue(
                    numericValue.Value >= 3,
                    $"Metric '{result.Key}' scored {numericValue.Value}/5, expected >= 3.");
            }
        }

        await scenario.DisposeAsync();
    }
}

using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace MyApp.Evals;

/// <summary>
/// Compare mode: runs the same prompts against two model configurations and
/// compares evaluation scores to detect regressions or improvements.
/// </summary>
[TestClass]
public class CompareTests
{
    private static readonly string BaselineModel =
        Environment.GetEnvironmentVariable("EVAL_BASELINE_MODEL") ?? "gpt-4o-mini";

    private static readonly string CandidateModel =
        Environment.GetEnvironmentVariable("EVAL_CANDIDATE_MODEL") ?? "gpt-4o";

    private record EvalResult(string Scenario, Dictionary<string, double> Scores);

    [TestMethod]
    public async Task Compare_CandidateDoesNotRegress()
    {
        var judgeClient = EvalConfig.CreateChatClient();
        var evaluators = EvalConfig.QualityEvaluators(judgeClient);

        var prompts = new[]
        {
            "I'm overwhelmed with work. What's one thing I can do right now?",
            "How do I build better habits?",
            "Give me a plan to learn a new programming language in 30 days."
        };

        var baselineScores = await RunSuite(BaselineModel, prompts, evaluators, "compare-baseline");
        var candidateScores = await RunSuite(CandidateModel, prompts, evaluators, "compare-candidate");

        for (int i = 0; i < prompts.Length; i++)
        {
            foreach (var metric in baselineScores[i].Scores.Keys)
            {
                var baseVal = baselineScores[i].Scores[metric];
                var candVal = candidateScores[i].Scores.GetValueOrDefault(metric);

                // Candidate should not drop more than 1 point below baseline
                Assert.IsTrue(
                    candVal >= baseVal - 1.0,
                    $"Regression on prompt[{i}] metric '{metric}': " +
                    $"baseline={baseVal}, candidate={candVal}");
            }
        }
    }

    private static async Task<EvalResult[]> RunSuite(
        string modelName,
        string[] prompts,
        IEvaluator[] evaluators,
        string scenarioPrefix)
    {
        var endpoint = Environment.GetEnvironmentVariable("AZURE_OPENAI_ENDPOINT") ?? "https://localhost";
        var apiKey = Environment.GetEnvironmentVariable("AZURE_OPENAI_API_KEY") ?? "";

        var azureClient = new Azure.AI.OpenAI.AzureOpenAIClient(
            new Uri(endpoint),
            new System.ClientModel.ApiKeyCredential(apiKey));

        IChatClient chatClient = azureClient.GetChatClient(modelName).AsIChatClient();

        var reporting = EvalConfig.CreateReportingConfig(
            $"{scenarioPrefix}-{modelName}", evaluators);

        var results = new List<EvalResult>();

        for (int i = 0; i < prompts.Length; i++)
        {
            var scenario = await reporting.CreateScenarioRunAsync(
                $"{scenarioPrefix}-prompt-{i}");

            var messages = new List<ChatMessage>
            {
                new(ChatRole.User, prompts[i])
            };

            var response = await chatClient.GetResponseAsync(messages);
            var modelResponse = response.Messages.Last();

            await scenario.EvaluateAsync(messages, modelResponse);

            var scores = new Dictionary<string, double>();
            foreach (var result in scenario.GetResults())
            {
                if (result.Value is NumericMetricValue numericValue)
                {
                    scores[result.Key] = numericValue.Value ?? 0;
                }
            }

            results.Add(new EvalResult(prompts[i], scores));
            await scenario.DisposeAsync();
        }

        return results.ToArray();
    }
}

