using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.Extensions.AI.Evaluation.Reporting.Storage;
using OpenAI;

namespace MyApp.Evals;

internal static class EvalConfig
{
    private static readonly string ModelName =
        Environment.GetEnvironmentVariable("EVAL_MODEL") ?? "gpt-4o-mini";

    private static readonly string Endpoint =
        Environment.GetEnvironmentVariable("AZURE_OPENAI_ENDPOINT") ?? "https://localhost";

    private static readonly string ApiKey =
        Environment.GetEnvironmentVariable("AZURE_OPENAI_API_KEY") ?? "";

    public static IChatClient CreateChatClient()
    {
        var client = new Azure.AI.OpenAI.AzureOpenAIClient(
            new Uri(Endpoint),
            new System.ClientModel.ApiKeyCredential(ApiKey));

        return client.GetChatClient(ModelName).AsIChatClient();
    }

    public static IEvaluator[] QualityEvaluators(IChatClient judge) =>
    [
        new RelevanceEvaluator(judge),
        new CoherenceEvaluator(judge),
        new FluencyEvaluator(judge),
        new GroundednessEvaluator(judge),
    ];

    public static ReportingConfiguration CreateReportingConfig(
        string scenarioName,
        IEvaluator[] evaluators)
    {
        var storage = new DiskBasedResultStorage(
            Path.Combine("eval-results", scenarioName));

        return new ReportingConfiguration(evaluators, storage);
    }
}

