using Microsoft.Extensions.AI;
using Microsoft.VisualStudio.TestTools.UnitTesting;
using OpenTelemetry;
using OpenTelemetry.Resources;
using OpenTelemetry.Trace;

namespace MyApp.Evals;

/// <summary>
/// Telemetry mode: validates that the agent emits expected spans and metrics
/// when OpenTelemetry is wired into the pipeline.
/// </summary>
[TestClass]
public class TelemetryTests
{
    private static readonly List<System.Diagnostics.Activity> ExportedActivities = [];

    private TracerProvider? _tracerProvider;

    [TestInitialize]
    public void Setup()
    {
        ExportedActivities.Clear();

        _tracerProvider = Sdk.CreateTracerProviderBuilder()
            .SetResourceBuilder(ResourceBuilder.CreateDefault().AddService("MyApp.Evals"))
            .AddSource("Microsoft.Extensions.AI")
            .AddSource("MyApp")
            .AddInMemoryExporter(ExportedActivities)
            .AddOtlpExporter(opt =>
            {
                var otlpEndpoint = Environment.GetEnvironmentVariable("OTEL_EXPORTER_OTLP_ENDPOINT");
                if (!string.IsNullOrEmpty(otlpEndpoint))
                    opt.Endpoint = new Uri(otlpEndpoint);
            })
            .Build();
    }

    [TestCleanup]
    public void Cleanup()
    {
        _tracerProvider?.Dispose();
    }

    [TestMethod]
    public async Task ChatCompletion_EmitsTraceSpan()
    {
        var innerClient = EvalConfig.CreateChatClient();
        using var client = new ChatClientBuilder(innerClient)
            .UseOpenTelemetry()
            .Build();

        await client.GetResponseAsync("What is 2+2?");

        _tracerProvider?.ForceFlush();

        Assert.IsTrue(
            ExportedActivities.Count > 0,
            "Expected at least one trace activity from the chat completion call.");
    }

    [TestMethod]
    public async Task ChatCompletion_SpanContainsModelAttribute()
    {
        var innerClient = EvalConfig.CreateChatClient();
        using var client = new ChatClientBuilder(innerClient)
            .UseOpenTelemetry()
            .Build();

        await client.GetResponseAsync("Say hello.");

        _tracerProvider?.ForceFlush();

        var span = ExportedActivities.FirstOrDefault();
        Assert.IsNotNull(span, "No span was exported.");

        var tags = span.Tags.ToDictionary(t => t.Key, t => t.Value);
        Assert.IsTrue(
            tags.ContainsKey("gen_ai.request.model") || tags.ContainsKey("gen_ai.response.model"),
            "Span should contain a model tag.");
    }
}

