using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace MyApp.Evals;

/// <summary>
/// Compare mode: runs the same prompts against two model configurations and
/// compares evaluation scores to detect regressions or improvements.
/// </summary>
[TestClass]
public class CompareTests
{
    private static readonly string BaselineModel =
        Environment.GetEnvironmentVariable("EVAL_BASELINE_MODEL") ?? "gpt-4o-mini";

    private static readonly string CandidateModel =
        Environment.GetEnvironmentVariable("EVAL_CANDIDATE_MODEL") ?? "gpt-4o";

    private record EvalResult(string Scenario, Dictionary<string, double> Scores);

    [TestMethod]
    public async Task Compare_CandidateDoesNotRegress()
    {
        var judgeClient = EvalConfig.CreateChatClient();
        var evaluators = EvalConfig.QualityEvaluators(judgeClient);

        var prompts = new[]
        {
            "I'm overwhelmed with work. What's one thing I can do right now?",
            "How do I build better habits?",
            "Give me a plan to learn a new programming language in 30 days."
        };

        var baselineScores = await RunSuite(BaselineModel, prompts, evaluators, "compare-baseline");
        var candidateScores = await RunSuite(CandidateModel, prompts, evaluators, "compare-candidate");

        for (int i = 0; i < prompts.Length; i++)
        {
            foreach (var metric in baselineScores[i].Scores.Keys)
            {
                var baseVal = baselineScores[i].Scores[metric];
                var candVal = candidateScores[i].Scores.GetValueOrDefault(metric);

                // Candidate should not drop more than 1 point below baseline
                Assert.IsTrue(
                    candVal >= baseVal - 1.0,
                    $"Regression on prompt[{i}] metric '{metric}': " +
                    $"baseline={baseVal}, candidate={candVal}");
            }
        }
    }

    private static async Task<EvalResult[]> RunSuite(
        string modelName,
        string[] prompts,
        IEvaluator[] evaluators,
        string scenarioPrefix)
    {
        var endpoint = Environment.GetEnvironmentVariable("AZURE_OPENAI_ENDPOINT") ?? "https://localhost";
        var apiKey = Environment.GetEnvironmentVariable("AZURE_OPENAI_API_KEY") ?? "";

        var azureClient = new Azure.AI.OpenAI.AzureOpenAIClient(
            new Uri(endpoint),
            new System.ClientModel.ApiKeyCredential(apiKey));

        IChatClient chatClient = azureClient.GetChatClient(modelName).AsIChatClient();

        var reporting = EvalConfig.CreateReportingConfig(
            $"{scenarioPrefix}-{modelName}", evaluators);

        var results = new List<EvalResult>();

        for (int i = 0; i < prompts.Length; i++)
        {
            var scenario = await reporting.CreateScenarioRunAsync(
                $"{scenarioPrefix}-prompt-{i}");

            var messages = new List<ChatMessage>
            {
                new(ChatRole.User, prompts[i])
            };

            var response = await chatClient.GetResponseAsync(messages);
            var modelResponse = response.Messages.Last();

            await scenario.EvaluateAsync(messages, modelResponse);

            var scores = new Dictionary<string, double>();
            foreach (var result in scenario.GetResults())
            {
                if (result.Value is NumericMetricValue numericValue)
                {
                    scores[result.Key] = numericValue.Value ?? 0;
                }
            }

            results.Add(new EvalResult(prompts[i], scores));
            await scenario.DisposeAsync();
        }

        return results.ToArray();
    }
}

